(1193, 12, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“而”的解释，正确的一项是', '[{"content":"<连>表转折；但是；却","correct":true},{"content":"<连>表承接；就；接着","correct":false},{"content":"<连>表因果；因而","correct":false},{"content":"<连>表转折","correct":false}]', 0, 0),
(1194, 12, 2, '下列句子中“而”的意义和用法，与例句相同的一项是', '[{"content":"浩浩乎如冯虚御风，<b>而</b>不知其所止；","correct":true},{"content":"公曰：“吾不能早用子，今急<b>而</b>求子，是寡人之过也。”","correct":false}]', 0, 0),
(1195, 13, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“于”的解释，正确的一项是', '[{"content":"<介>在；从；到","correct":true},{"content":"<介>比","correct":false},{"content":"<介>和；跟；同","correct":false},{"content":"<介>向；对；对于","correct":false}]', 0, 0),
(1196, 13, 2, '下列句子中“于”的意义和用法，与例句相同的一项是', '[{"content":"壬戌之秋，七月既望，苏子与客泛舟游<b>于</b>赤壁之下。","correct":true},{"content":"吾师道也，夫庸知其年之先后生<b>于</b>吾乎？","correct":false}]', 0, 0),
(1197, 14, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“之”的解释，正确的一项是', '[{"content":"<代>第三人称代词；他；她；它（们）","correct":true},{"content":"<助>相当于现代汉语的“的”","correct":false},{"content":"<代>指示代词；这；此","correct":false},{"content":"<助>放在主语和谓语之间，取消句子独立性","correct":false}]', 0, 0),
(1198, 14, 2, '下列句子中“之”的意义和用法，与例句相同的一项是', '[{"content":"秦时与臣游，项伯杀人，臣活<b>之</b>。","correct":true},{"content":"古<b>之</b>学者必有师。","correct":false}]', 0, 0),
(1199, 15, 1, '下列对例句“虽有槁暴，不复挺者，輮使之然也。”中“者”的解释，正确的一项是', '[{"content":"<助>放在分句末，引出原因","correct":true},{"content":"<助>用在数词后；……个；……样东西；……件事情","correct":false},{"content":"<助>指人、物、事、时、地等；……的（人、东西、事情）","correct":false},{"content":"<助>用在时间词后，表示停顿","correct":false}]', 0, 0),
(1200, 15, 2, '下列句子中“者”的意义和用法，与例句相同的一项是', '[{"content":"暂无例句","correct":true},{"content":"范增数目项王，举所佩玉玦以示之<b>者</b>三。","correct":false}]', 0, 0),
(1201, 16, 1, '下列对例句“虽有槁暴，不复挺者，輮使之然也。”中“也”的解释，正确的一项是', '[{"content":"<助>句末语气词；表陈述、解释","correct":true},{"content":"<反义>与“句末语气词；表陈述、解释”相反","correct":false},{"content":"<字面义>按“也”字面理解","correct":false},{"content":"<字面义>“也”的本义","correct":false}]', 0, 0),
(1202, 16, 2, '下列句子中“也”的意义和用法，与例句相同的一项是', '[{"content":"愿伯具言臣之不敢倍德<b>也</b>。","correct":true},{"content":"暂无例句","correct":false}]', 0, 0),
(1203, 26, 1, '下列对例句“古之学者必有师。”中“之”的解释，正确的一项是', '[{"content":"<助>相当于现代汉语的“的”","correct":true},{"content":"<代>第三人称代词；他；她；它（们）","correct":false},{"content":"<代>指示代词；这；此","correct":false},{"content":"<助>放在主语和谓语之间，取消句子独立性","correct":false}]', 0, 0),
(1204, 26, 2, '下列句子中“之”的意义和用法，与例句相同的一项是', '[{"content":"壬戌<b>之</b>秋，七月既望，苏子与客泛舟游于赤壁<b>之</b>下。","correct":true},{"content":"青，取<b>之</b>于蓝，而青于蓝；","correct":false}]', 0, 0),
(1205, 27, 1, '下列对例句“惑而不从师，其为惑也，终不解矣。”中“其”的解释，正确的一项是', '[{"content":"<代>第三人称代词；他；它；他们","correct":true},{"content":"<代>第三人称代词；他的；它的；他们的","correct":false},{"content":"<代>代词，他们的","correct":false},{"content":"<代>代词，它的，指狼","correct":false}]', 0, 0),
(1206, 27, 2, '下列句子中“其”的意义和用法，与例句相同的一项是', '[{"content":"王若隐<b>其</b>无罪而就死地，则牛羊何择焉？","correct":true},{"content":"浩浩乎如冯虚御风，而不知<b>其</b>所止；","correct":false}]', 0, 0),
(1207, 29, 1, '下列对例句“吾师道也，夫庸知其年之先后生于吾乎？”中“于”的解释，正确的一项是', '[{"content":"<介>比","correct":true},{"content":"<介>在；从；到","correct":false},{"content":"<介>和；跟；同","correct":false},{"content":"<介>向；对；对于","correct":false}]', 0, 0),
